+
+/** 创建符合 API 客户端读取方式的最小 JSON 响应。 */
+function jsonResponse(body: unknown): Response {
+  return {
+    ok: true,
+    status: 200,
+    statusText: 'OK',
+    text: async () => JSON.stringify(body),
+  } as Response;
+}
+
+/** 为认证刷新与应用壳初始化提供确定性响应，未知只读端点统一返回空集合。 */
+function stubShellFetch(): void {
