+function renderSemanticApp(locale: AppLocale) {
+  return render(
+    <AppIntlProvider initialLocale={locale}>
+      <App />
+    </AppIntlProvider>,
+  );
+}
+
+beforeEach(() => {
+  stubBrowserApis();
+  stubShellFetch();
+  window.localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify({
