+  const numberOptions: Intl.NumberFormatOptions = { maximumFractionDigits: 2 };
+  const currencyOptions: Intl.NumberFormatOptions = {
+    currency: 'USD',
+    maximumFractionDigits: 2,
+    style: 'currency',
