+      expect(rawNodes.some((node) => node.textContent?.includes('tool output: keep verbatim'))).toBe(true);
+      expect(rawNodes.some((node) => node.textContent?.includes('session state: keep verbatim'))).toBe(true);
+      view.unmount();
+    }
+  });
+});

